an class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/swoole-process.usequeue.php" class="methodname" style="color:#CC7832">useQueue</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/swoole-process.wait.php" class="methodname" style="color:#CC7832">wait</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$blocking</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/swoole-process.write.php" class="methodname" style="color:#CC7832">write</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>   }</div>  </div>  <div class="section" id="swoole-process.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="swoole-process.constants.ipc-nowait"><strong><span>{@link Swoole\Process::IPC_NOWAIT}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Swoole\Process::alarm} — High precision timer which triggers signal with fixed interval.</li><li>{@link Swoole\Process::close} — Close the pipe to the child process.</li><li>{@link Swoole\Process::__construct} — Construct a process.</li><li>{@link Swoole\Process::daemon} — Change the process to be a daemon process.</li><li>{@link Swoole\Process::__destruct} — Destroy the process.</li><li>{@link Swoole\Process::exec} — Execute system commands.</li><li>{@link Swoole\Process::exit} — Stop the child processes.</li><li>{@link Swoole\Process::freeQueue} — Destroy the message queue created by swoole_process::useQueue.</li><li>{@link Swoole\Process::kill} — Send signal to the child process.</li><li>{@link Swoole\Process::name} — Set name of the process.</li><li>{@link Swoole\Process::pop} — Read and pop data from the message queue.</li><li>{@link Swoole\Process::push} — Write and push data into the message queue.</li><li>{@link Swoole\Process::read} — Read data sending to the process.</li><li>{@link Swoole\Process::signal} — Send signal to the child processes.</li><li>{@link Swoole\Process::start} — Start the process.</li><li>{@link Swoole\Process::statQueue} — Get the stats of the message queue used as the communication method between processes.</li><li>{@link Swoole\Process::useQueue} — Create a message queue as the communication method between the parent process and child processes.</li><li>{@link Swoole\Process::wait} — Wait for the events of child processes.</li><li>{@link Swoole\Process::write} — Write data into the pipe and communicate with the parent process or child processes.</li></ul></div>
 */
class Process
{
    public const IPC_NOWAIT = 256;
    public const PIPE_MASTER = 1;
    public const PIPE_WORKER = 2;
    public const PIPE_READ = 3;
    public const PIPE_WRITE = 4;
    public $pipe;
    public $msgQueueId;
    public $msgQueueKey;

    /**
     * Process ID. This is to uniquely identify the process in the OS.
     *
     * @var int
     */
    public $pid;

    /**
     * ID of the process.
     *
     * In a Swoole program (e.g., a Swoole-based server), there are different types of processes, including event worker
     * processes, task worker processes, and user worker processes. This ID is to uniquely identify the process in the
     * running Swoole program.
     *
     * @var int
     */
    public $id;
    private $callback;

/**
 * <div id="swoole-process.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Process::__construct</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Process::__construct</span> — <span class="dc-title">Construct a process.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-process.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Process::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$redirect_stdin_and_stdout</span><span class="initializer"> = ?</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$pipe_type</span><span class="initializer"> = ?</span></span>)</div>  <p class="para rdfs-comment">  </p> </div> <div class="refsect1 parameters" id="refsect1-swoole-process.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>     <p class="para">           </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">redirect_stdin_and_stdout</span></dt>    <dd>     <p class="para">           </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">pipe_type</span></dt>    <dd>     <p class="para">           </p>    </dd>     </dl> </div> </div>
 */
    public function __construct(callable $callback, $redirect_stdin_and_stdout = null, $pipe_type = null, $enable_coroutine = null) {}

/**
 * <div id="swoole-process.destruct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Swoole\Process::__destruct</h1>  <p class="verinfo">(PECL swoole &gt;= 1.9.0)</p><p class="refpurpose"><span class="refname">Swoole\Process::__destruct</span> — <span class="dc-title">Destroy the process.</span></p> </div> <div class="refsect1 description" id="refsect1-swoole-process.destruct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Swoole\Process::__destruct</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">  </p> </div> <div class="refsect1 parameters" id="refsect1-swoole-process.destruct-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-swoole-process.destruct-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">     </p> </div></div>
